type Token = { t: "num"; v: number } | { t: "id"; v: string } | { t: "op"; v: string }

function tokenize(src: string): Token[] {
  const out: Token[] = []
  let i = 0
  while (i < src.length) {
    const c = src[i] as string
    if (/\s/.test(c)) {
      i++
    } else if (/[0-9.]/.test(c)) {
      const m = /^(?:\d+\.?\d*|\.\d+)(?:e[+-]?\d+)?/i.exec(src.slice(i))
      if (!m) throw new Error(`Unexpected "${c}"`)
      out.push({ t: "num", v: Number(m[0]) })
      i += m[0].length
    } else if (/[A-Za-z_]/.test(c)) {
      const m = /^[A-Za-z_][A-Za-z0-9_]*/.exec(src.slice(i)) as RegExpExecArray
      out.push({ t: "id", v: m[0] })
      i += m[0].length
    } else if ("+-*/%^(),".includes(c)) {
      out.push({ t: "op", v: c })
      i++
    } else {
      throw new Error(`Unexpected "${c}"`)
    }
  }
  return out
}

/* -------------------------------------------------------------------------------------------------
 * Formula evaluation: a small recursive descent parser. No eval, no globals.
 * -----------------------------------------------------------------------------------------------*/

const FUNCTIONS: Record<string, (...args: number[]) => number> = {
  min: Math.min,
  max: Math.max,
  round: (v, d = 0) => Math.round(v * 10 ** d) / 10 ** d,
  floor: Math.floor,
  ceil: Math.ceil,
  abs: Math.abs,
  sqrt: Math.sqrt,
  pow: Math.pow,
  log: Math.log,
  exp: Math.exp,
}

/** Evaluates an arithmetic formula against named values. Throws on syntax errors or unknown names. */
export function evaluateFormula(formula: string, scope: Record<string, number>): number {
  const tokens = tokenize(formula)
  let pos = 0
  const peek = () => tokens[pos]
  const take = (v?: string) => {
    const tok = tokens[pos]
    if (!tok || (v !== undefined && tok.v !== v)) throw new Error(`Expected "${v ?? "value"}"`)
    pos++
    return tok
  }
  const expr = (): number => {
    let left = term()
    while (peek()?.t === "op" && (peek()?.v === "+" || peek()?.v === "-")) {
      const op = take().v
      const right = term()
      left = op === "+" ? left + right : left - right
    }
    return left
  }
  const term = (): number => {
    let left = unary()
    while (peek()?.t === "op" && ["*", "/", "%"].includes(peek()?.v as string)) {
      const op = take().v
      const right = unary()
      left = op === "*" ? left * right : op === "/" ? left / right : left % right
    }
    return left
  }
  const unary = (): number => {
    if (peek()?.t === "op" && peek()?.v === "-") {
      take()
      return -unary()
    }
    if (peek()?.t === "op" && peek()?.v === "+") {
      take()
      return unary()
    }
    return power()
  }
  const power = (): number => {
    const base = atom()
    if (peek()?.t === "op" && peek()?.v === "^") {
      take()
      return base ** unary()
    }
    return base
  }
  const atom = (): number => {
    const tok = take()
    if (tok.t === "num") return tok.v
    if (tok.t === "id") {
      if (peek()?.t === "op" && peek()?.v === "(") {
        const fn = FUNCTIONS[tok.v]
        if (!fn) throw new Error(`Unknown function "${tok.v}"`)
        take("(")
        const args: number[] = []
        if (peek()?.v !== ")") {
          args.push(expr())
          while (peek()?.v === ",") {
            take(",")
            args.push(expr())
          }
        }
        take(")")
        return fn(...args)
      }
      if (tok.v === "PI") return Math.PI
      if (!(tok.v in scope)) throw new Error(`Unknown name "${tok.v}"`)
      return scope[tok.v] as number
    }
    if (tok.v === "(") {
      const v = expr()
      take(")")
      return v
    }
    throw new Error(`Unexpected "${tok.v}"`)
  }
  const value = expr()
  if (pos < tokens.length) throw new Error(`Unexpected "${tokens[pos]?.v}"`)
  return value
}

/* -------------------------------------------------------------------------------------------------
 * Types
 * -----------------------------------------------------------------------------------------------*/

export type CalculatorFormat = "number" | "currency" | "percent" | "integer"

export interface CalculatorInput {
  name: string
  label: string
  min: number
  max: number
  step?: number
  defaultValue?: number
  /** `percent` shows the raw number with a % sign: 4.5 reads 4.5%. */
  format?: CalculatorFormat
  unit?: string
  hint?: string
}

export interface CalculatorOutput {
  name: string
  label: string
  /**
   * Arithmetic over input names and earlier outputs: `principal * (1 + rate / 100) ^ years`.
   * Supports + - * / % ^, parentheses and min, max, round, floor, ceil, abs, sqrt, pow, log, exp.
   */
  formula?: string
  format?: CalculatorFormat
  unit?: string
  /** The headline result. The first output is primary when none is marked. */
  primary?: boolean
  hint?: string
  /** Computed for later formulas and the breakdown, but not listed (avoids showing a part twice). */
  hidden?: boolean
}

export interface CalculatorBreakdown {
  label: string
  formula: string
}

export type CalculatorValues = Record<string, number>

export interface CalculatorWidgetProps extends Omit<React.ComponentProps<"div">, "title" | "onSubmit"> {
  title?: React.ReactNode
  description?: React.ReactNode
  inputs?: CalculatorInput[]
  outputs?: CalculatorOutput[]
  /** Parts of a whole, drawn as a proportion bar under the results. */
  breakdown?: CalculatorBreakdown[]
  /** Compute results in code instead of formulas. Wins over `formula` for the keys it returns. */
  compute?: (values: CalculatorValues) => CalculatorValues
  values?: CalculatorValues
  defaultValues?: CalculatorValues
  onValuesChange?: (values: CalculatorValues) => void
  /** Adds a button that sends the current numbers back to the agent. */
  onSubmit?: (values: CalculatorValues, results: CalculatorValues) => void
  submitLabel?: string
  currency?: string
  locale?: string
  streaming?: boolean
  loading?: boolean
  variant?: "card" | "plain"
}

/* -------------------------------------------------------------------------------------------------
 * CalculatorWidget
 * -----------------------------------------------------------------------------------------------*/

function useResults(
  inputs: CalculatorInput[],
  outputs: CalculatorOutput[],
  breakdown: CalculatorBreakdown[],
  values: CalculatorValues,
  compute?: CalculatorWidgetProps["compute"],
) {
  return React.useMemo(() => {
    const scope: Record<string, number> = {}
    for (const input of inputs)
      scope[input.name] = values[input.name] ?? input.defaultValue ?? input.min
    const computed = compute ? compute({ ...scope }) : {}
    const results: CalculatorValues = {}
    const errors: Record<string, string> = {}
    // Outputs may reference each other in any order (a total listed before its parts), so
    // evaluate in passes until nothing new resolves.
    let pending = outputs
    for (let pass = 0; pass <= outputs.length && pending.length > 0; pass++) {
      const next: CalculatorOutput[] = []
      for (const out of pending) {
        if (out.name in computed) {
          results[out.name] = computed[out.name] as number
        } else if (out.formula) {
          try {
            results[out.name] = evaluateFormula(out.formula, scope)
            delete errors[out.name]
          } catch (err) {
            errors[out.name] = err instanceof Error ? err.message : "Invalid formula"
            next.push(out)
          }
        }
        if (out.name in results) scope[out.name] = results[out.name] as number
      }
      if (next.length === pending.length) break
      pending = next
    }
    const parts = breakdown.flatMap((b) => {
      try {
        return [{ label: b.label, value: evaluateFormula(b.formula, scope) }]
      } catch {
        return []
      }
    })
    return { results, errors, parts }
  }, [inputs, outputs, breakdown, values, compute])
}

/* -------------------------------------------------------------------------------------------------
 * Helpers
 * -----------------------------------------------------------------------------------------------*/

const NBSP = " "

function formatNumber(
  value: number,
  format: CalculatorFormat = "number",
  {
    currency = "USD",
    locale = "en-US",
    unit,
  }: { currency?: string; locale?: string; unit?: string } = {},
) {
  if (!Number.isFinite(value)) return "-"
  let text: string
  if (format === "currency") {
    text = new Intl.NumberFormat(locale, {
      style: "currency",
      currency,
      maximumFractionDigits: Math.abs(value) >= 1000 ? 0 : 2,
    }).format(value)
  } else if (format === "percent") {
    text = `${new Intl.NumberFormat(locale, { maximumFractionDigits: 2 }).format(value)}%`
  } else if (format === "integer") {
    text = new Intl.NumberFormat(locale, { maximumFractionDigits: 0 }).format(value)
  } else {
    text = new Intl.NumberFormat(locale, { maximumFractionDigits: 2 }).format(value)
  }
  return unit ? `${text}${NBSP}${unit}` : text
}

