function clamp(v: number, input: CalculatorInput) {
  const step = input.step ?? 1
  const snapped = Math.round((v - input.min) / step) * step + input.min
  return Math.min(input.max, Math.max(input.min, Number(snapped.toFixed(10))))
}

/** Exact entry next to the slider. Commits on blur or Enter and snaps to the step and range. */
function NumberField({
  input,
  value,
  onCommit,
  label,
  currency = "USD",
  locale = "en-US",
}: {
  input: CalculatorInput
  value: number
  onCommit: (v: number) => void
  label: string
  currency?: string
  locale?: string
}) {
  const [draft, setDraft] = React.useState<string | null>(null)
  const prefix =
    input.format === "currency"
      ? (new Intl.NumberFormat(locale, { style: "currency", currency })
          .formatToParts(0)
          .find((p) => p.type === "currency")?.value ?? "")
      : ""
  const suffix = input.format === "percent" ? "%" : input.unit ? input.unit : ""
  const commit = () => {
    if (draft === null) return
    const n = Number(draft.replace(/[^0-9.-]/g, ""))
    if (draft.trim() !== "" && Number.isFinite(n)) onCommit(n)
    setDraft(null)
  }
  return (
    <span
      className={cn(
        // One width for every field, with or without a prefix or suffix, so the column lines up.
        "rounded-(--chatcn-radius-sm) bg-(color:--chatcn-card) shadow-(--chatcn-shadow-xs) inline-flex h-7 w-24 shrink-0 items-center gap-0.5 px-2 pointer-coarse:h-11",
        "focus-within:shadow-(--chatcn-shadow-input-focus) ease-(--chatcn-ease-standard) transition-shadow duration-150",
      )}
    >
      {prefix ? <span className="text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg-subtle)">{prefix}</span> : null}
      <input
        aria-label={label}
        inputMode="decimal"
        value={draft ?? new Intl.NumberFormat(locale, { maximumFractionDigits: 4 }).format(value)}
        onChange={(e) => setDraft(e.target.value)}
        onFocus={(e) => e.currentTarget.select()}
        onBlur={commit}
        onKeyDown={(e) => {
          if (e.key === "Enter" && !e.nativeEvent.isComposing) commit()
          if (e.key === "Escape") setDraft(null)
          if (e.key === "ArrowUp" || e.key === "ArrowDown") {
            e.preventDefault()
            onCommit(clamp(value + (e.key === "ArrowUp" ? 1 : -1) * (input.step ?? 1), input))
          }
        }}
        className="text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg) min-w-0 flex-1 bg-transparent text-end font-medium tabular-nums outline-none"
      />
      {suffix ? <span className="text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg-subtle)">{suffix}</span> : null}
    </span>
  )
}

/* -------------------------------------------------------------------------------------------------
 * Slider: a native range input over a drawn track, so keyboard, touch and RTL stay native.
 * -----------------------------------------------------------------------------------------------*/

function CalculatorSlider({
  input,
  value,
  id,
  onChange,
  valueText,
  disabled,
}: {
  input: CalculatorInput
  value: number
  id: string
  onChange: (v: number) => void
  valueText: string
  disabled?: boolean
}) {
  const pct = ((value - input.min) / (input.max - input.min || 1)) * 100
  return (
    <span className="group/slider relative flex h-6 items-center pointer-coarse:h-11">
      <span aria-hidden="true" className="bg-(color:--chatcn-gray-300) absolute inset-x-0 h-1 rounded-full" />
      <span
        aria-hidden="true"
        className="bg-(color:--chatcn-accent) absolute start-0 h-1 rounded-full"
        style={{ width: `${pct}%` }}
      />
      <span
        aria-hidden="true"
        className={cn(
          "bg-(color:--chatcn-card) shadow-(--chatcn-shadow-sm) absolute size-4 rounded-full",
          "ease-(--chatcn-ease-out) transition-[scale,box-shadow] duration-150",
          "group-has-[:focus-visible]/slider:outline-(color:--chatcn-accent) group-has-[:active]/slider:scale-110 group-has-[:focus-visible]/slider:outline-2 group-has-[:focus-visible]/slider:outline-offset-2",
          "dark:shadow-(--chatcn-shadow-border) dark:bg-(color:--chatcn-fg)",
        )}
        style={{ insetInlineStart: `calc(${pct}% - ${(pct / 100) * 16}px)` }}
      />
      <input
        id={id}
        type="range"
        min={input.min}
        max={input.max}
        step={input.step ?? 1}
        value={value}
        disabled={disabled}
        aria-valuetext={valueText}
        onChange={(e) => onChange(Number(e.target.value))}
        className="absolute inset-0 m-0 w-full cursor-pointer appearance-none opacity-0 disabled:cursor-default"
      />
    </span>
  )
}

/* -------------------------------------------------------------------------------------------------
 * Proportion bar: the pie alternative. One 100% bar, 2 px gaps, labelled rows underneath.
 * -----------------------------------------------------------------------------------------------*/

interface ProportionItem {
  label: string
  value: number
}

interface ProportionBarProps extends React.ComponentProps<"div"> {
  items: ProportionItem[]
  format?: (value: number) => string
  /** Bar thickness in px. */
  size?: number
  /** Hide the labelled rows under the bar. */
  hideLabels?: boolean
  streaming?: boolean
  highlight?: string
}

/* -------------------------------------------------------------------------------------------------
 * Encodings
 *
 * Series take the categorical chart palette (`--chatcn-chart-1` to `-6`): hues picked to stay
 * distinct for the common color blindness types. Lines also keep distinct dash patterns and end
 * markers, and every chart has a legend and a data table, so no series depends on hue alone.
 * -----------------------------------------------------------------------------------------------*/

type Fill =
  | { kind: "solid"; color: string }
  | { kind: "hatch" | "dots"; color: string; ground: string; angle: number }

const FILLS: Fill[] = [
  { kind: "solid", color: "var(--chatcn-chart-1)" },
  { kind: "solid", color: "var(--chatcn-chart-2)" },
  { kind: "solid", color: "var(--chatcn-chart-3)" },
  { kind: "solid", color: "var(--chatcn-chart-4)" },
  { kind: "solid", color: "var(--chatcn-chart-5)" },
  { kind: "solid", color: "var(--chatcn-chart-6)" },
]

/* -------------------------------------------------------------------------------------------------
 * Swatches and patterns
 * -----------------------------------------------------------------------------------------------*/

function PatternDefs({ id }: { id: string }) {
  return (
    <defs>
      {FILLS.map((fill, i) =>
        fill.kind === "solid" ? null : (
          <pattern
            key={i}
            id={`${id}-p${i}`}
            patternUnits="userSpaceOnUse"
            width={fill.kind === "dots" ? 4 : 5}
            height={fill.kind === "dots" ? 4 : 5}
            patternTransform={fill.kind === "hatch" ? `rotate(${fill.angle})` : undefined}
          >
            <rect width="5" height="5" fill={fill.ground} />
            {fill.kind === "hatch" ? (
              <line x1="0" y1="0" x2="0" y2="5" stroke={fill.color} strokeWidth="2" />
            ) : (
              <circle cx="2" cy="2" r="0.9" fill={fill.color} />
            )}
          </pattern>
        ),
      )}
    </defs>
  )
}

function fillFor(id: string, index: number) {
  const fill = FILLS[index % FILLS.length] as Fill
  return fill.kind === "solid" ? fill.color : `url(#${id}-p${index % FILLS.length})`
}

type Marker = "circle" | "square" | "diamond" | "triangle"

const STROKES: { color: string; dash?: string; marker: Marker }[] = [
  { color: "var(--chatcn-chart-1)", marker: "circle" },
  { color: "var(--chatcn-chart-2)", marker: "square" },
  { color: "var(--chatcn-chart-3)", dash: "6 4", marker: "diamond" },
  { color: "var(--chatcn-chart-4)", dash: "2 4", marker: "triangle" },
  { color: "var(--chatcn-chart-5)", marker: "circle" },
  { color: "var(--chatcn-chart-6)", dash: "6 4", marker: "square" },
]

/** Legend and tooltip key. Mirrors the mark: a filled square for bars, a short stroke for lines. */
function SeriesKey({ index, kind }: { index: number; kind: "fill" | "line" }) {
  const id = React.useId()
  if (kind === "line") {
    const stroke = STROKES[index % STROKES.length] as (typeof STROKES)[number]
    return (
      <svg aria-hidden="true" width="14" height="8" className="shrink-0 overflow-visible">
        <line
          x1="1"
          y1="4"
          x2="13"
          y2="4"
          stroke={stroke.color}
          strokeWidth="2"
          strokeLinecap="round"
          strokeDasharray={stroke.dash ? stroke.dash.replace("6 4", "4 3") : undefined}
        />
      </svg>
    )
  }
  return (
    <svg aria-hidden="true" width="10" height="10" className="shrink-0">
      <PatternDefs id={id} />
      <rect width="10" height="10" rx="2.5" fill={fillFor(id, index)} />
    </svg>
  )
}

function ProportionBar({
  items,
  format = (v) => String(v),
  size = 12,
  hideLabels,
  streaming,
  highlight,
  className,
  ...props
}: ProportionBarProps) {
  const id = React.useId()
  const positive = items.filter((it) => it.value > 0)
  const total = positive.reduce((n, it) => n + it.value, 0)
  const percent = new Intl.NumberFormat("en-US", { style: "percent", maximumFractionDigits: 0 })
  return (
    <div data-slot="proportion-bar" className={cn("flex flex-col gap-3", className)} {...props}>
      <div className="flex w-full gap-0.5 overflow-hidden" style={{ height: size }}>
        {total === 0 ? (
          <div className="bg-(color:--chatcn-fill) rounded-(--chatcn-radius-xs) h-full flex-1" />
        ) : (
          positive.map((it, _i) => (
            <svg
              key={it.label}
              aria-hidden="true"
              data-slot="chart-mark"
              data-enter={streaming ? "fade" : undefined}
              className={cn(
                "h-full min-w-0.5 shrink-0 first:rounded-s-[4px] last:rounded-e-[4px]",
                "ease-(--chatcn-ease-out) transition-[opacity] duration-150",
                highlight !== undefined && highlight !== it.label && "opacity-40",
              )}
              style={{ flexBasis: `calc(${(it.value / total) * 100}% - 2px)`, flexGrow: 1 }}
            >
              <PatternDefs id={id} />
              <rect width="100%" height="100%" fill={fillFor(id, items.indexOf(it))} />
            </svg>
          ))
        )}
      </div>
      {hideLabels ? null : (
        <ul className="grid grid-cols-[repeat(auto-fill,minmax(10rem,1fr))] gap-x-4 gap-y-1.5">
          {items.map((it, i) => (
            <li key={it.label} className="text-[0.8125rem]/[1.25rem] flex min-w-0 items-center gap-2">
              <SeriesKey index={i} kind="fill" />
              <span className="text-(color:--chatcn-fg-muted) min-w-0 truncate">{it.label}</span>
              <span className="text-(color:--chatcn-fg) ms-auto shrink-0 font-medium tabular-nums">
                {total > 0 ? percent.format(Math.max(0, it.value) / total) : "-"}
              </span>
              <span className="text-(color:--chatcn-fg-subtle) text-[0.75rem]/[1rem] shrink-0 tabular-nums">
                {format(it.value)}
              </span>
            </li>
          ))}
        </ul>
      )}
    </div>
  )
}

