/**
 * A small interactive tool inside an answer: sliders and number fields on one side, live results
 * on the other. Formulas come from the spec and run through a tiny arithmetic parser.
 */
export function CalculatorWidget({
  title,
  description,
  inputs: inputsProp,
  outputs: outputsProp,
  breakdown: breakdownProp,
  compute,
  values: valuesProp,
  defaultValues,
  onValuesChange,
  onSubmit,
  submitLabel = "Use these numbers",
  currency,
  locale,
  streaming = false,
  loading = false,
  variant = "card",
  className,
  ...props
}: CalculatorWidgetProps) {
  const inputs = React.useMemo(
    () =>
      (inputsProp ?? []).filter(
        (i) =>
          i && typeof i.name === "string" && typeof i.min === "number" && typeof i.max === "number",
      ),
    [inputsProp],
  )
  const outputs = React.useMemo(
    () => (outputsProp ?? []).filter((o) => o && typeof o.name === "string" && o.label),
    [outputsProp],
  )
  const breakdown = React.useMemo(
    () => (breakdownProp ?? []).filter((b) => b?.label && typeof b.formula === "string"),
    [breakdownProp],
  )
  const [state, setState] = React.useState<CalculatorValues>(() => ({ ...defaultValues }))
  const values = valuesProp ?? state
  const inputValue = (input: CalculatorInput) =>
    values[input.name] ?? input.defaultValue ?? input.min
  const set = (name: string, v: number) => {
    const next = { ...values, [name]: v }
    if (valuesProp === undefined) setState(next)
    onValuesChange?.(next)
  }
  const { results, errors, parts } = useResults(inputs, outputs, breakdown, values, compute)
  const primary = outputs.find((o) => o.primary) ?? outputs[0]
  const rest = outputs.filter((o) => o !== primary && !o.hidden)
  const id = React.useId()
  const pending = loading || (streaming && inputs.length === 0)
  const fmt = (v: number, f?: CalculatorFormat, unit?: string) =>
    formatNumber(v, f, { currency, locale, unit })
  const changed = inputs.some(
    (i) =>
      values[i.name] !== undefined &&
      values[i.name] !== (defaultValues?.[i.name] ?? i.defaultValue),
  )

  // Announce the headline once the user stops adjusting, not on every slider step.
  const [announced, setAnnounced] = React.useState("")
  const primaryText =
    primary && primary.name in results
      ? fmt(results[primary.name] as number, primary.format, primary.unit)
      : ""
  React.useEffect(() => {
    if (!primary || !primaryText) return
    const t = window.setTimeout(() => setAnnounced(`${primary.label}: ${primaryText}`), 700)
    return () => window.clearTimeout(t)
  }, [primary, primaryText])

  const isCard = variant === "card"

  return (
    <div
      data-slot="calculator-widget"
      aria-busy={pending || streaming || undefined}
      className={cn(
        "text-[0.875rem]/[1.25rem] tracking-[-0.003em] text-(color:--chatcn-fg) flex min-w-0 flex-col",
        isCard && "rounded-(--chatcn-radius-lg) bg-(color:--chatcn-card) shadow-(--chatcn-shadow-sm)",
        className,
      )}
      {...props}
    >
      {title || description ? (
        <div className={cn("flex items-start gap-3", isCard ? "px-4 pt-4" : "")}>
          <div className="flex min-w-0 flex-1 flex-col gap-0.5">
            {title ? <h3 className="font-medium text-balance">{title}</h3> : null}
            {description ? (
              <p className="text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg-subtle) text-pretty">{description}</p>
            ) : null}
          </div>
          {changed ? (
            <Button
              size="xs"
              onClick={() => {
                const next = { ...defaultValues }
                if (valuesProp === undefined) setState(next)
                onValuesChange?.(next)
              }}
              className="-me-1 shrink-0 pointer-coarse:h-11"
            >
              <RotateCcwIcon />
              Reset
            </Button>
          ) : null}
        </div>
      ) : null}

      <div
        className={cn(
          "grid gap-4 sm:grid-cols-[minmax(0,1fr)_minmax(0,0.9fr)]",
          isCard ? "p-4" : "py-4",
        )}
      >
        <div className="flex min-w-0 flex-col gap-4">
          {pending
            ? [0, 1, 2].map((i) => (
                <div key={i} aria-hidden="true" className="flex flex-col gap-2.5">
                  <span className="bg-(color:--chatcn-fill) rounded-(--chatcn-radius-xs) h-3 w-28" />
                  <span className="bg-(color:--chatcn-fill) h-1 w-full rounded-full" />
                </div>
              ))
            : inputs.map((input) => {
                const value = inputValue(input)
                const text = fmt(value, input.format, input.unit)
                return (
                  <div
                    key={input.name}
                    data-slot="calculator-input"
                    className="flex flex-col gap-1"
                  >
                    <div className="flex items-center justify-between gap-3">
                      <label
                        htmlFor={`${id}-${input.name}`}
                        className="text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg-muted) font-medium"
                      >
                        {input.label}
                      </label>
                      <NumberField
                        input={input}
                        value={value}
                        onCommit={(v) => set(input.name, clamp(v, input))}
                        label={input.label}
                        currency={currency}
                        locale={locale}
                      />
                    </div>
                    <CalculatorSlider
                      id={`${id}-${input.name}`}
                      input={input}
                      value={value}
                      valueText={text}
                      onChange={(v) => set(input.name, v)}
                    />
                    <div
                      className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) flex justify-between tabular-nums"
                      aria-hidden="true"
                    >
                      <span>{fmt(input.min, input.format, input.unit)}</span>
                      {input.hint ? <span className="truncate px-2">{input.hint}</span> : null}
                      <span>{fmt(input.max, input.format, input.unit)}</span>
                    </div>
                  </div>
                )
              })}
        </div>

        <div
          className="bg-(color:--chatcn-inset) rounded-(--chatcn-radius-md) flex min-w-0 flex-col gap-4 p-4"
          data-slot="calculator-results"
        >
          {primary ? (
            <div className="flex flex-col gap-0.5">
              <span className="text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg-subtle)">{primary.label}</span>
              {primary.name in results ? (
                <span className="text-[2rem]/[2.5rem] tracking-[-0.028em] text-(color:--chatcn-fg) font-semibold tracking-tight tabular-nums">
                  {primaryText}
                </span>
              ) : (
                <span
                  aria-hidden="true"
                  className="bg-(color:--chatcn-fill) rounded-(--chatcn-radius-xs) my-2 block h-7 w-36"
                />
              )}
              {errors[primary.name] ? (
                <span className="text-[0.75rem]/[1rem] text-(color:--chatcn-red)">
                  Formula error: {errors[primary.name]}
                </span>
              ) : primary.hint ? (
                <span className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) text-pretty">
                  {primary.hint}
                </span>
              ) : null}
            </div>
          ) : (
            <span aria-hidden="true" className="bg-(color:--chatcn-fill) rounded-(--chatcn-radius-xs) block h-16 w-40" />
          )}

          {rest.length > 0 ? (
            <dl className="border-(color:--chatcn-border) flex flex-col gap-1.5 border-t pt-3">
              {rest.map((o) => (
                <div
                  key={o.name}
                  className="text-[0.8125rem]/[1.25rem] flex items-baseline justify-between gap-3"
                >
                  <dt className="text-(color:--chatcn-fg-subtle)">{o.label}</dt>
                  <dd className="text-(color:--chatcn-fg) font-medium tabular-nums">
                    {o.name in results ? (
                      fmt(results[o.name] as number, o.format, o.unit)
                    ) : errors[o.name] ? (
                      <span className="text-(color:--chatcn-red) font-normal">Formula error</span>
                    ) : (
                      <span className="text-(color:--chatcn-fg-subtle)">-</span>
                    )}
                  </dd>
                </div>
              ))}
            </dl>
          ) : null}

          {parts.length > 1 ? (
            <ProportionBar
              items={parts}
              size={8}
              format={(v) => fmt(v, primary?.format === "currency" ? "currency" : "number")}
              className="mt-auto [&_ul]:grid-cols-1"
            />
          ) : null}
        </div>
      </div>

      {onSubmit ? (
        <div
          className={cn(
            "flex justify-end",
            isCard ? "border-(color:--chatcn-border) border-t px-4 py-3" : "",
          )}
        >
          <Button
            size="sm"
            variant="outline"
            disabled={streaming || pending}
            onClick={() =>
              onSubmit(
                { ...Object.fromEntries(inputs.map((i) => [i.name, inputValue(i)])) },
                results,
              )
            }
            className="pointer-coarse:h-11"
          >
            <SendIcon />
            {submitLabel}
          </Button>
        </div>
      ) : null}

      <span aria-live="polite" aria-atomic="true" className="sr-only">
        {announced}
      </span>
    </div>
  )
}

export default CalculatorWidget

